fn main() { let mut b = sourcemap::SourceMapBuilder::new(Some("probe.mjs")); let a=b.add_source("same.can"); let d=b.add_source("same.can"); println!("source_ids={a},{d}"); let x=b.add_name("x"); let xx=b.add_name("x"); println!("name_ids={x},{xx}"); b.add_raw(0,0,0,6,Some(d),Some(x),false); b.add_raw(2,0,0,0,None,None,false); let map=b.into_sourcemap(); let mut bytes=Vec::new(); map.to_writer(&mut bytes).unwrap(); println!("{}",String::from_utf8(bytes).unwrap()); }